function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a1f14', S='#6b6358', SL='#8a8276', SD='#4a443c';
  px(4,8,24,18,O);
  px(5,9,22,16,S);
  px(5,9,22,2,SL); px(5,23,22,2,SD);
  px(8,12,16,8,SD);
  px(10,14,12,4,SL);
}
